#include <stdio.h>
#include <string.h>

int main(void) {
    const char *p = "ababaca";
    int m = (int)strlen(p), next[16];
    next[0] = 0;
    for (int i = 1, len = 0; i < m; ) {
        if (p[i] == p[len])      next[i++] = ++len;   /* 前后缀可延伸 */
        else if (len > 0)        len = next[len - 1]; /* 退到更短的公共前后缀 */
        else                     next[i++] = 0;       /* 无公共前后缀 */
    }
    printf("模式串: %s\n", p);
    printf("下标  :");
    for (int i = 0; i < m; i++) printf(" %d", i);
    printf("\n字符  :");
    for (int i = 0; i < m; i++) printf(" %c", p[i]);
    printf("\nnext  :");
    for (int i = 0; i < m; i++) printf(" %d", next[i]);
    printf("\n");
    return 0;
}
